2. Configure Cypress to use Docker

   - In your Cypress project's root directory, create a new `.dockerignore` file with the following content:

     ```text
     node_modules
     cypress
     *.map
     ```

   - In your Cypress project's root directory, create a new `docker-compose.yml` file with the following content:

     ```yaml
     version: '3'

     services:
       cypress:
         build:
           context: .
         ports:
           - "8080:8080"
         volumes:
           - .:/app
     ```

   - In your Cypress project's root directory, create a new `cypress.json` file with the following content:

     ```json
     {
       "baseUrl": "http://localhost:8080",
       "video": false,
       "screenshots": {
         "directory": "cypress/screenshots",
         "onLastFailedTest": true
       },
       "reporter": "mocha",
       "reporterOptions": {
         "reporterEnabled": "mocha"
       }
     }
     ```

3. Write your Cypress tests

   - Create your Cypress tests in the `cypress/integration` directory.
   - Use Cypress commands to capture and save screenshots:

     ```javascript
     // Import required Cypress commands
     import { captureScreenshot, saveScreenshot } from './commands';

     describe('My Test Suite', () => {
       it('Captures and saves a screenshot', () => {
         // Navigate to a page that should render a specific element
         cy.visit('/');

         // Capture a screenshot of the element
         const element = '#my-element';
         const screenshot = captureScreenshot(element);

         // Save the screenshot with a descriptive name
         saveScreenshot('my-element', screenshot);
       });
     });
     ```

   - Create a new `commands.js` file in your Cypress project's root directory with the following content:

     ```javascript
     import Cypress from 'cypress';

     const captureScreenshot = (selector: string): Cypress.JQuery<HTMLElement> => {
       const element = Cypress.$(selector);
       const boundingRect = element[0].getBoundingClientRect();
       const screenshot = Cypress.capture('element', element);
       const croppedScreenshot = screenshot
         .crop(boundingRect.left, boundingRect.top, boundingRect.width, boundingRect.height)
         .toBuffer();
       return croppedScreenshot;
     };

     const saveScreenshot = (fileName: string, screenshot: Buffer): void => {
       Cypress.config('screenshotsFolder', 'cypress/screenshots');
       Cypress.writeFile(`cypress/screenshots/${fileName}.png`, screenshot);
     };

     export { captureScreenshot, saveScreenshot };
     ```

4. Run your Cypress tests using Docker

   - In your Cypress project's root directory, run `docker-compose up` to build and start the Cypress container.
   - In another terminal, navigate to your Cypress project's root directory and run `npm run test` to run your Cypress tests.

That's it! Your Cypress test framework now utilizes Docker and allows for capturing and saving screenshots using the commands provided in the `commands.js` file. Make sure to customize the `cypress.json` file to fit your project's needs.

Hier ist eine C++ Funktion, die einen Markdown-String in einen HTML-String konvertiert:

```cpp
#include <string>
#include <sstream>
#include <iostream>
#include <boost/algorithm/string.hpp>

// Function to convert Markdown to HTML
std::string markdownToHtml(const std::string& markdown) {
    // Create a stringstream to parse the Markdown input
    std::stringstream ss(markdown);

    // Create a stringstream to build the HTML output
    std::stringstream html;

    // Helper functions to parse Markdown and generate HTML
    void bold(std::string& str);
    void italic(std::string& str);
    void header(std::string& str, int level);
    void list(std::string& str, bool is_ordered);
    void link(std::string& str);

    // Parse Markdown and generate HTML
    std::string token;
    while (getline(ss, token, '\n')) {
        boost::algorithm::trim(token);

        // Process individual Markdown tokens
        if (token.empty()) {
            // Ignore empty lines
        } else if (token[0] == '#') {
            header(token, std::stoi(token.substr(1)) + 1);
        } else if (token[0] == '*') {
            italic(token);
        } else if (token[0] == '_') {
            bold(token);
        } else if (boost::starts_with(token, "[") && boost::ends_with(token, "]")) {
            link(token.substr(1, token.find(']') - 1));
        } else if (boost::starts_with(token, "-") || boost::starts_with(token, "+") || boost::starts_with(token, "*")) {
            list(token.substr(2), boost::starts_with(token, "-") || boost::starts_with(token, "+"));
        } else {
            html << "<p>" << token << "</p>\n";
        }
    }

    // Return the generated HTML
    return html.str();
}

// Helper functions to parse Markdown and generate HTML

void bold(std::string& str) {
    std::string left = "<strong>";
    std::string right = "</strong>";
    boost::algorithm::replace_all(str, "**", left + right);
}

void italic(std::string& str) {
    std::string left = "<em>";
    std::string right = "</em>";
    boost::algorithm::replace_all(str, "* ", left);
    boost::algorithm::replace_all(str, " *", right);
}

void header(std::string& str, int level) {
    std::string tag = "<h" + std::to_string(level) + ">";
    boost::algorithm::replace_all(str, "#", tag);
}

void list(std::string& str, bool is_ordered) {
    std::string tag = is_ordered ? "<ol>" : "<ul>";
    std::string end_tag = is_ordered ? "</ol>" : "</ul>";
    boost::algorithm::replace_all(str, "\n", "\n" + tag + "\n");
    boost::algorithm::replace_all(str, "- ", "<li>");
    boost::algorithm::replace_all(str, "+ ", "<li>");
    boost::algorithm::replace_all(str, "* ", "<li>");
    boost::algorithm::replace_all(str, end_of_line + "</li>\n", "</li>\n" + end_tag);
}

void link(std::string& str) {
    std::size_t pos = str.find("]");
    std::string url = str.substr(str.find("(") + 1, pos - str.find("(") - 1);
    std::string text = str.substr(1, pos - 1);
    html << "<a href='" << url << "'>" << text << "</a>";
}

int main() {
    std::string markdown = "### Header\n"
                            "**Bold text**\n"
                            "*Italic text*\n"
                            "\n"
                            "- List item 1\n"
                            "+ List item 2\n"
                            "* List item 3\n"
                            "\n"
                            "[Google](https://www.google.com/)";

    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Dieses Beispiel konvertiert einfachen Markdown-Text in HTML. Um es für mehr komplexe Markdown-Formatierungen zu erweitern, benötigt es weiterer Funktionalität, wie z.B. Unterstützung für Bildeinbindungen, Tabellen oder Codeausschnitte. Die Boost C++ Bibliothek bietet auch hilfreiche Tools für die Markdown-Verarbeitung.

